package com.zzy.ksongfloat.ai; import com.zzy.ksongfloat.ai.model.*; public class AiResponseValidator { public void validate(AiAnalysisResult r) throws Exception { if(r.commentSuggestions==null||r.privateMessageSuggestions==null) throw new Exception("suggestions 字段缺失"); if(r.commentSuggestions.isEmpty()&&r.privateMessageSuggestions.isEmpty()&&r.profileSummary.isEmpty()) throw new Exception("AI 返回缺少可用内容"); } }
